440	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
441	// filtered by label — never the search index, for the same reason the work-item
442	// list is not (S6/F11): a mark this list misses is a request that silently waits an
443	// hour, and one it misses TWICE is a request nobody notices was never picked up.
444	//
445	// The author's push permission comes back with each issue, because adoption gates
446	// the body's parameters on it (PRINCIPLES.md) and the payload's `author_association` is not
447	// that fact: `MEMBER` is any org member whatever their repo permission, and
448	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
449	// leaves the flag `null`, which gates the parameters off — the safe end of a field
450	// that chooses a task, a model, or the right to land a change without review.
451	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
452	  const out = [];
453	  const push = permissionOf ?? (async (login) => {
454	    const res = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
455	    if (res.status === 404) return false;
456	    if (res.status !== 200) return null;
457	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
458	  });
459	  const cache = new Map();
460	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
461	  // comma-separated list selects the issues carrying EVERY name on it — so asking
462	  // for both marks at once asks for issues wearing both, which nothing does. The
463	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
464	  // or in a template, decoded forever like every legacy spelling (PRINCIPLES.md), and that
465	  // costs a second listing rather than a wider one.
466	  const seen = new Map();
467	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
468	    for (let page = 1; ; page += 1) {
469	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
470	      const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
471	      // A list that could not be READ is not a list that is EMPTY, and the two are
472	      // indistinguishable downstream: adoption simply finds nothing to do and the run
473	      // reports success. Every request then waits for a person to notice, which is
474	      // the one thing this lane exists so nobody has to do.
475	      if (status !== 200 || !Array.isArray(json)) {
476	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
477	      }
478	      if (json.length === 0) break;
479	      for (const i of json) {
480	        if (i.pull_request) continue;
481	        // A filed work item wearing the mark is not a request awaiting adoption: it is
482	        // already an item, and re-adopting one would rewrite its body under the run
483	        // holding it.
484	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
485	        // ANY status means this mark has been adopted — the exactly-once guard (PRINCIPLES.md).
486	        // Filtering here rather than in the plan keeps the permission reads to the
487	        // issues actually awaiting adoption.
488	        if (statusOf(i) !== null) continue;
489	        // An issue wearing both spellings comes back from both listings; it is one
490	        // request, and adopting it twice would rewrite the body of the item the first
491	        // adoption just made.
492	        if (seen.has(i.number)) continue;
493	        const author = i.user?.login ?? null;
494	        if (author && !cache.has(author)) cache.set(author, await push(author));
495	        seen.set(i.number, {
496	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
497	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
498	        });
499	      }
500	      if (json.length < 100) break;
501	    }
502	  }
503	  out.push(...seen.values());
504	  return out;
505	}
