762	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
763	// executor only when this run's parting look at the queue found something
764	// pickable. On a quiet repo that is the difference between 24 executor runs a day
765	// and none.
766	//
767	// This is the run's LAST act, after the forced wake: a wake readies items, and a
768	// look taken before it would send the hour's forced work to the next cron fire.
769	//
770	// The delivery is unweakened by the gate. A label event may be lost, and what a
771	// lost event would have delivered is exactly what this look sees — the queue
772	// itself, read live, by the same pick rule the executor applies. Where the
773	// output cannot be written (a run outside Actions, an older member workflow that
774	// maps no output) the drain job's own default decides, and the run says which
775	// happened rather than going quiet about it.
776	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
777	// this run itself readied is the other, and the second needs no confirmation —
778	// GitHub's issue list is eventually consistent, so an item created milliseconds
779	// earlier can be absent from it (#1340). Trusting the read alone left a forced
780	// `update` sitting `task:ready` until the next cron fire on three members at once.
781	// Ordering stays the executor's job: this only decides whether to start one.
782	export function pickableCount(open, readiedThisRun = [], opts = {}) {
783	  const listed = pickOrder(open, opts).map((i) => i.number);
784	  return new Set([...listed, ...readiedThisRun]).size;
785	}
786	
787	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
788	  const { listOpenWorkItems } = await import('./read.mjs');
789	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
790	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
791	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
792	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
793	    scheduledOf: (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null),
794	    pathTo: (p) => byPath.get(p) ?? null,
795	  });
796	  console.log(pickable
797	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
798	    : '- nothing pickable — no executor is dispatched this run');
799	  const out = process.env.GITHUB_OUTPUT;
800	  if (!out) return;
801	  const { appendFileSync } = await import('node:fs');
802	  appendFileSync(out, `pickable=${pickable ? 'true' : 'false'}\n`);
803	}
804	
805	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
806	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
807	// point that must be able to start the same run without being this module.
808	export { main as runSchedulerRun };
809	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
810	  main().catch((e) => { console.error(e); process.exit(1); });
811	}
812	
813	export { parseWorkItemTitle };
814

